// Project cardinal references supplied by HPC. Coordinates come from each floor's grid.
export const HPC_CARDINAL={version:'HPC-cardinal-1',source:'Referencia del proyecto: norte A, sur W, este 12 (cordillera), oeste 1 (mar)',north:'AA',south:'AW',east:'A12',west:'A1'};
const dot=(a,b)=>a[0]*b[0]+a[1]*b[1];
function toward(a,b){if(!a||!b)return null;const v=[a.b[0]-a.a[0],a.b[1]-a.a[1]],len=Math.hypot(...v);if(!len)return null;let n=[-v[1]/len,v[0]/len];const w=[b.b[0]-b.a[0],b.b[1]-b.a[1]],wl=Math.hypot(...w);if(!wl||Math.abs(dot(n,w)/wl)>.001)return null;const d=dot([b.a[0]-a.a[0],b.a[1]-a.a[1]],n);return Math.abs(d)<1e-6?null:n.map(x=>x*Math.sign(d));}
const calibrations=new Map();
export function calibrate(grid,reference){const key=reference?.sha256?reference.nivel+':'+reference.sha256:null;if(key&&calibrations.has(key))return calibrations.get(key);const axis=id=>grid?.ejes?.find(e=>e.id===id),north=toward(axis('AW'),axis('AA')),east=toward(axis('A1'),axis('A12'));const value=north&&east&&Math.abs(dot(north,east))<.05?{...HPC_CARDINAL,north,east,reference}:null;if(key)calibrations.set(key,value);return value;}
export function orientedEdges(points,calibration){if(!points?.length)return [];const signed=points.reduce((n,a,i)=>{const b=points[(i+1)%points.length];return n+a[0]*b[1]-b[0]*a[1];},0);const counts={};return points.map((a,i)=>{const b=points[(i+1)%points.length],dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy),normal=len?[dy/len*Math.sign(signed),-dx/len*Math.sign(signed)]:null;let direction='Orientación pendiente de verificación';if(normal&&calibration){const n=dot(normal,calibration.north),e=dot(normal,calibration.east);direction=Math.abs(n)>.94?(n>0?'Norte':'Sur'):Math.abs(e)>.94?(e>0?'Este':'Oeste'):(n>0?'Norte':'Sur')+'-'+(e>0?'Este':'Oeste');}const key=[a,b].map(p=>p.map(x=>Number(x.toFixed(3))).join(',')).sort().join('|');counts[direction]=(counts[direction]||0)+1;return {key,points:[a,b],direction,label:direction+' '+String(counts[direction]).padStart(2,'0'),kind:'tramo-contorno',physicalWallVerified:false,calibration};});}
export function recommend({quantity,unit,rate,rateUnit,basis='persona-dia',days,hours,crew,status='provisional',source}){
 if(unit!==rateUnit)return {state:'unavailable',message:'La unidad del rendimiento no coincide con la cantidad comprometida.'};
 if(days===0)return {state:'unavailable',message:'El plazo no contiene días laborables en el calendario base.'};
 if(![quantity,rate,days].every(n=>Number.isFinite(n)&&n>0)||!['persona-dia','persona-hora','cuadrilla-dia','cuadrilla-hora'].includes(basis)||unit!==rateUnit||!source)return {state:'unavailable',message:'Rendimiento pendiente de calibración'};
 const byCrew=basis.startsWith('cuadrilla'),hourly=basis.endsWith('hora');if(hourly&&(!Number.isFinite(hours)||!(hours>0)||hours>24)||byCrew&&(!crew?.length||crew.some(r=>!r.role||!Number.isSafeInteger(r.count)||!(r.count>0))))return {state:'unavailable',message:'Completa las horas efectivas o la composición de cuadrilla.'};
 const capacity=rate*days*(hourly?hours:1),resources=Math.ceil(quantity/capacity),people=byCrew?resources*crew.reduce((n,r)=>n+r.count,0):resources;
 return {state:status==='validado'?'validated':'provisional',resources,people,perResource:capacity,label:resources+' '+(byCrew?'cuadrillas':'personas'),message:`${quantity} ${unit} / (${rate} ${unit}/${basis} × ${days} días${hourly?' × '+hours+' h/día':''})`,source};
}
